import{_ as t,o as s,c as a,X as i}from"./chunks/framework.pSp8ynCZ.js";const k=JSON.parse('{"title":"Documentation development","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/contributing.md","filePath":"contributing.md"}'),n={name:"rust/docs/contributing.md"};function o(d,e,r,l,p,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="documentation-development" tabindex="-1">Documentation development <a class="header-anchor" href="#documentation-development" aria-label="Permalink to &quot;Documentation development&quot;">​</a></h1><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>This website has an English Rust manual at <code>/rust/</code> and a Python manual at <code>/python/</code>, under one CellPack project homepage. VitePress 1.6.4 renders the manual and landing page. Its theme extension supplies the homepage, typography, navigation and logo player, while VitePress supplies local search, page outlines, syntax highlighting, and code copying.</p><p>Authored guides and module contracts are ordinary Markdown files in this directory. <code>reference.py</code> derives the public interface pages and catalogs from rustdoc. <code>examples/</code> is an independent Cargo package whose Rust sources are included directly in guide pages.</p><table tabindex="0"><thead><tr><th>File or directory</th><th>Purpose</th></tr></thead><tbody><tr><td><code>.vitepress/config.mjs</code></td><td>Site navigation, search, deployment base and build paths</td></tr><tr><td><code>package.json / package-lock.json</code></td><td>Pinned VitePress frontend dependencies</td></tr><tr><td><code>pyproject.toml / uv.lock</code></td><td>Python tools for API generation</td></tr><tr><td><code>build.py</code></td><td>Rustdoc, API generation, example validation and site build</td></tr><tr><td><code>reference.py</code></td><td>Declarations, member indexes, parameters, returns and field documentation</td></tr><tr><td><code>_catalog/</code></td><td>Generated module catalogs and sidebar metadata</td></tr><tr><td><code>generated-*.md</code></td><td>Generated public-interface pages</td></tr><tr><td><code>_build/rustdoc/</code></td><td>Private compiler output used to extract API metadata</td></tr><tr><td><code>_build/html/</code></td><td>Complete static website</td></tr></tbody></table><p>The Python bindings are not installed or imported to build this manual.</p><p>The canonical brand asset is <code>assets/logo.svg</code> at the repository root. The build copies it to the public directory for the navbar, homepage illustration, and browser icon. Update that source asset instead of editing a generated copy.</p><p><code>assets/cellpack-animation.svg</code> supplies the homepage animation. A small default-theme extension in <code>.vitepress/theme/</code> adds its player and navbar hover feedback. The player runs once, supports pause/replay, pauses outside the viewport or in background tabs, and falls back to the static logo for reduced-motion preferences.</p><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From the repository root, on a machine where compilation is allowed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.96.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RUSTUP_TOOLCHAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1.96.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/build.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check-examples</span></span></code></pre></div><p>The build generates version-matched rustdoc, refreshes the public-interface catalog, runs every complete guide program when requested, and builds the website with VitePress. Missing document links fail the frontend build. Rustdoc warnings also fail the build.</p><p>Open <code>docs/cellpack/_build/html/index.html</code> through a local web server. For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/_build/html</span></span></code></pre></div><p>When previewing on a remote compute node, forward that port through your SSH connection. Follow your environment&#39;s proxy and compute-node rules for package installation, compilation, and browser checks.</p><h2 id="live-editing" tabindex="-1">Live editing <a class="header-anchor" href="#live-editing" aria-label="Permalink to &quot;Live editing&quot;">​</a></h2><p>Prepare generated content, then start the VitePress development server:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RUSTUP_TOOLCHAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1.96.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack/build.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prepare-only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/cellpack</span></span></code></pre></div><p>Markdown edits refresh automatically. After changing Rust public interfaces or their documentation, run the preparation step again. <code>--site-only</code> renders already prepared content; <code>--output</code> selects another HTML directory; <code>--base /en/latest/</code> builds for a URL prefix.</p><h2 id="authoring" tabindex="-1">Authoring <a class="header-anchor" href="#authoring" aria-label="Permalink to &quot;Authoring&quot;">​</a></h2><p>Use ordinary Markdown links for manual pages. The API generator produces the searchable interface pages and links directly between them. Compiler output remains private to the build. Edit Rust documentation and module contracts rather than generated files.</p><p>VitePress includes Rust source directly with <code>&lt;&lt;&lt; @/examples/quickstart.rs</code>.</p><p>Use <code>&lt;DocDiagram name=&quot;…&quot; /&gt;</code> for authored workflow diagrams, identity maps, matrix fixtures and decision cards. Their shared content is in <code>.vitepress/theme/components/doc-diagrams.mjs</code>; <code>DocDiagram.vue</code> renders it with theme colors and responsive layouts. Keep parameter tables, executable source and actual terminal output in Markdown. Edit authored pages rather than generated API declarations or <code>_catalog</code> files.</p><p>Module references include generated Markdown catalogs with the standard VitePress Markdown-include directive. Keep source examples executable, small, and independent of external datasets.</p><p>Rust sidebar API entries follow <code>_catalog/navigation.json</code>. Route namespaces, compatibility links, and subsite counterparts are defined in <code>.vitepress/routes.mjs</code>. Python reference sections are extracted from <code>docs/python-api.md</code> by <code>python_docs.py</code>; training pages include the maintained programs in <code>example/</code> directly. The subsite layout, badge switcher, and breadcrumbs live in <code>.vitepress/theme/site/</code>. Navigation and sidebars are configured in <code>.vitepress/config.mjs</code>. Theme components and styles live in <code>.vitepress/theme/</code>. <code>HeroLogo.vue</code> owns the SVG timeline and accepts the page&#39;s pause state so the homepage motion control also stops its animation.</p><h2 id="read-the-docs" tabindex="-1">Read the Docs <a class="header-anchor" href="#read-the-docs" aria-label="Permalink to &quot;Read the Docs&quot;">​</a></h2><p>Use <code>docs/cellpack/.readthedocs.yaml</code> as the project&#39;s build configuration. It selects Python 3.12, Rust 1.96, and Node.js 24. Its custom build commands bootstrap the uv tool, install the locked Python and Node dependencies, and build into <code>$READTHEDOCS_OUTPUT/html</code>.</p><p>The deployment base defaults to the English Read the Docs version path. Set <code>CELLPACK_DOCS_BASE</code> explicitly for a different mount point. Local builds default to <code>/</code>.</p><ol><li>Push the source, configuration, and Python/Node/Cargo lockfiles to your Git host.</li><li>Import the repository in Read the Docs.</li><li>Select <code>docs/cellpack/.readthedocs.yaml</code> as the build configuration.</li><li>Build the intended branch and review the generated site.</li><li>Activate the release versions you want to publish.</li></ol><p>Rust and Python share this build and deployment base. The Python reference is prepared from source text without importing optional Python integrations or building another extension wheel. Each subsite keeps its own navigation and search scope. Clicking its product name returns to its home; Project home returns to <code>/</code>.</p><p>Official references: <a href="https://vuejs.github.io/vitepress/v1/" target="_blank" rel="noreferrer">VitePress</a>, <a href="https://docs.readthedocs.com/platform/stable/build-customization.html" target="_blank" rel="noreferrer">Read the Docs custom builds</a>, and <a href="https://docs.readthedocs.com/platform/stable/guides/setup/monorepo.html" target="_blank" rel="noreferrer">multiple projects in one repository</a>.</p><h2 id="dependency-updates" tabindex="-1">Dependency updates <a class="header-anchor" href="#dependency-updates" aria-label="Permalink to &quot;Dependency updates&quot;">​</a></h2><p>Update Python dependencies through <code>uv add --project docs/cellpack ...</code>. Update frontend dependencies in this directory and commit <code>package-lock.json</code>. The guide programs have their own <code>examples/Cargo.lock</code>. Rebuild and validate after dependency or toolchain changes.</p>`,33)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
